//#region src/custom_domains_api.ts
const customDomainsPath = (projectId, branchId) => `/projects/${encodeURIComponent(projectId)}/branches/${encodeURIComponent(branchId)}/custom-domains`;
const listCustomDomains = async (apiClient, projectId, branchId, { cursor, limit } = {}) => {
	const { data } = await apiClient.request({
		path: customDomainsPath(projectId, branchId),
		method: "GET",
		query: {
			cursor,
			limit
		},
		secure: true,
		format: "json"
	});
	return {
		custom_domains: data.custom_domains ?? [],
		next: data.pagination?.next
	};
};
const registerCustomDomain = async (apiClient, projectId, branchId, input) => {
	const { data } = await apiClient.request({
		path: customDomainsPath(projectId, branchId),
		method: "POST",
		body: input,
		format: "json",
		secure: true
	});
	return data;
};
const deleteCustomDomain = async (apiClient, projectId, branchId, domain) => {
	await apiClient.request({
		path: `${customDomainsPath(projectId, branchId)}/${encodeURIComponent(domain)}`,
		method: "DELETE",
		secure: true
	});
};
//#endregion
export { deleteCustomDomain, listCustomDomains, registerCustomDomain };
